package com.antra.payment; import com.fasterxml.jackson.annotation.JsonAutoDetect; import jakarta.persistence.*; import java.math.*; import java.time.*;
@Entity @Table(name="payments") @JsonAutoDetect(fieldVisibility=JsonAutoDetect.Visibility.ANY) class Payment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(unique=true,nullable=false) Long reservationId; @Column(nullable=false) String username; @Column(nullable=false) BigDecimal amount; @Column(nullable=false) String status; Instant paidAt; protected Payment(){} Payment(Long r,String u,BigDecimal a){reservationId=r;username=u;amount=a;status="SUCCESS";paidAt=Instant.now();}}
